#!/usr/bin/env node
// gen-modulepreload.mjs — flatten the cold-boot ES-module waterfall.
//
// WHY THIS EXISTS
// ---------------
// The app ships ~179 local ES modules served unbundled (scene3d 65, plugins
// 81, ui 27). With native ESM the browser can only DISCOVER an import after it
// has fetched + parsed the importer — so a deep static graph loads essentially
// one round-trip *per level*, serialized. A cold-cache network capture showed
// 193 JS requests taking ~58s almost entirely that way.
//
// `<link rel="modulepreload">` breaks the discovery dependency: the browser is
// told the whole boot module graph up front and fetches every unit in parallel
// (bounded only by the connection/HTTP-2 stream budget) while it is still
// parsing the entry script. No bundler, no source edits, no change to module
// resolution — the lowest-risk way to collapse the waterfall.
//
// WHAT IT DOES
//   1. Seeds = every RELATIVE module specifier in index.html (static `from`,
//      side-effect `import "..."`, AND eager dynamic `import("...")`).
//   2. Transitive crawl follows ONLY static imports. A dynamic `import()`
//      inside a module is an intentional lazy boundary (particles on first
//      entity, atmosphere post-login, …) — preloading past it would pull
//      chunks the boot path may never need, so we stop there.
//   3. Emits one <link rel="modulepreload" href="..."> per reached unit,
//      PRESERVING the exact `?v=` query string from the import (the browser
//      keys preloads by full URL — `x.js` and `x.js?v=1` are different
//      resources, so a mismatch silently wastes the preload).
//   4. Only emits links for files that exist on disk (drops comment/string
//      false-positives and stale paths so we never inject a 404 preload).
//   5. Rewrites the block between the BEGIN/END markers in index.html, in
//      place, idempotently. Re-run after adding/removing imports.
//
// USAGE
//   node scripts/gen-modulepreload.mjs            # rewrite index.html in place
//   node scripts/gen-modulepreload.mjs --check    # exit 1 if out of date (CI)
//   node scripts/gen-modulepreload.mjs --print    # print the block, no write

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, resolve, relative } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, ".."); // apps/holtburger-web
const INDEX = resolve(ROOT, "index.html");

const BEGIN = "<!-- BEGIN modulepreload (generated by scripts/gen-modulepreload.mjs — do not edit by hand) -->";
const END = "<!-- END modulepreload -->";

// Match: `from "spec"`, side-effect `import "spec"`, and dynamic `import("spec")`.
// Captures the specifier; group 1 = static-from/side-effect, group 2 = dynamic.
const STATIC_RE = /(?:\bfrom|\bimport)\s*["']([^"']+)["']/g;
const DYNAMIC_RE = /\bimport\s*\(\s*["']([^"']+)["']\s*\)/g;

const isRelative = (s) => s.startsWith("./") || s.startsWith("../");
const stripQuery = (s) => s.split("?", 1)[0];

/** Read a file's source. For index.html we only want the inline module scripts,
 *  but scanning the whole document is harmless: the regexes only match JS import
 *  syntax and we existence-check every hit before emitting. */
function readSource(absNoQuery) {
  try {
    return readFileSync(absNoQuery, "utf8");
  } catch {
    return null;
  }
}

/** Collect specifiers from source. `followDynamic` = include dynamic import()
 *  (true only for the index.html seeds). Returns array of raw specifiers. */
function collectSpecifiers(src, followDynamic) {
  const out = [];
  for (const m of src.matchAll(STATIC_RE)) out.push(m[1]);
  if (followDynamic) {
    for (const m of src.matchAll(DYNAMIC_RE)) out.push(m[1]);
  }
  return out;
}

// hrefByKey: fsPath(no query) -> href(with query as first seen). We dedupe the
// crawl by on-disk file, but keep the queried URL for the link tag.
const hrefByFsPath = new Map();
const visited = new Set(); // fsPaths whose imports we've already crawled

function consider(specifier, importerDirAbs) {
  if (!isRelative(specifier)) return null; // bare specifiers resolve via importmap; skip
  const noQuery = stripQuery(specifier);
  const fsPath = resolve(importerDirAbs, noQuery);
  if (!existsSync(fsPath)) return null; // false positive or stale path — never preload a 404
  // Keep the first href we see for this file (queried form preferred if present).
  if (!hrefByFsPath.has(fsPath) || (specifier.includes("?") && !hrefByFsPath.get(fsPath).includes("?"))) {
    hrefByFsPath.set(fsPath, specifier);
  }
  return fsPath;
}

// 1) Seeds from index.html (static + eager dynamic).
const indexSrc = readFileSync(INDEX, "utf8");
const queue = [];
for (const spec of collectSpecifiers(indexSrc, /* followDynamic */ true)) {
  const fsPath = consider(spec, ROOT);
  if (fsPath) queue.push(fsPath);
}

// 2) Transitive crawl — static imports only.
while (queue.length) {
  const fsPath = queue.shift();
  if (visited.has(fsPath)) continue;
  visited.add(fsPath);
  const src = readSource(fsPath);
  if (src == null) continue;
  const dir = dirname(fsPath);
  for (const spec of collectSpecifiers(src, /* followDynamic */ false)) {
    const child = consider(spec, dir);
    if (child && !visited.has(child)) queue.push(child);
  }
}

// 3) Build the link block. href is relative-to-ROOT with the original query,
//    normalised to a leading "./" so it matches the document's own specifiers.
const hrefs = [...hrefByFsPath.entries()]
  .map(([fsPath, originalSpec]) => {
    const rel = relative(ROOT, stripQuery(fsPath)).split("\\").join("/");
    const query = originalSpec.includes("?") ? "?" + originalSpec.split("?").slice(1).join("?") : "";
    return `./${rel}${query}`;
  })
  .sort();

const lines = hrefs.map((h) => `    <link rel="modulepreload" href="${h}">`);
const block = `${BEGIN}\n${lines.join("\n")}\n    ${END}`;

// 4) Splice into index.html between the markers, inserting them right after the
//    importmap </script> on first run.
function splice(html) {
  const bi = html.indexOf(BEGIN);
  const ei = html.indexOf(END);
  if (bi !== -1 && ei !== -1) {
    return html.slice(0, bi) + block + html.slice(ei + END.length);
  }
  // First run: anchor after the importmap script close tag.
  const anchor = '</script>';
  const importmapIdx = html.indexOf('<script type="importmap">');
  if (importmapIdx === -1) throw new Error("could not find <script type=\"importmap\"> anchor in index.html");
  const closeIdx = html.indexOf(anchor, importmapIdx) + anchor.length;
  return html.slice(0, closeIdx) + "\n\n    " + block + html.slice(closeIdx);
}

const mode = process.argv[2];
const next = splice(indexSrc);

if (mode === "--print") {
  process.stdout.write(block + "\n");
  console.error(`[gen-modulepreload] ${hrefs.length} modules in boot graph`);
} else if (mode === "--check") {
  if (next !== indexSrc) {
    console.error("[gen-modulepreload] index.html modulepreload block is STALE — run `node scripts/gen-modulepreload.mjs`");
    process.exit(1);
  }
  console.error(`[gen-modulepreload] up to date (${hrefs.length} modules)`);
} else {
  if (next !== indexSrc) {
    writeFileSync(INDEX, next);
    console.error(`[gen-modulepreload] wrote ${hrefs.length} modulepreload links into index.html`);
  } else {
    console.error(`[gen-modulepreload] no change (${hrefs.length} modules)`);
  }
}
